begin;set local lock_timeout='2s';set local statement_timeout='15s';do $qa$ declare n integer;other_hash text;begin select md5(jsonb_agg(to_jsonb(b) order by b.id)::text) into other_hash from raid_bosses b where id<>'1023c0f0-6025-4d53-af36-ef7cfa4f4e71';if (select count(*) from raid_room_members where room_id='ee8b0e8a-1e25-43f1-bf09-30e37081d774')<>3 or exists(select 1 from raid_room_members where room_id='ee8b0e8a-1e25-43f1-bf09-30e37081d774' and user_id not in('fadc944c-0b15-472c-be4d-305c26d8163f','25975265-f042-4dd1-8ffc-a12f8414a035','5c53fd8d-245b-49da-8ca6-b7afd6b7e6f0')) then raise exception 'QA member mismatch';end if;if exists(select 1 from battle_replay_sessions where source_reference_id='1023c0f0-6025-4d53-af36-ef7cfa4f4e71' and finalization_status='PENDING') then raise exception 'pending replay';end if;update raid_bosses b set current_hp=1000 where b.id='1023c0f0-6025-4d53-af36-ef7cfa4f4e71' and current_hp=33974394 and max_hp=34000000 and status='ACTIVE' and exists(select 1 from raid_rooms r where r.id='ee8b0e8a-1e25-43f1-bf09-30e37081d774' and r.raid_boss_instance_id=b.id and r.owner_user_id='fadc944c-0b15-472c-be4d-305c26d8163f');get diagnostics n=row_count;if n<>1 then raise exception 'QA HP prior mismatch';end if;if other_hash is distinct from (select md5(jsonb_agg(to_jsonb(b) order by b.id)::text) from raid_bosses b where id<>'1023c0f0-6025-4d53-af36-ef7cfa4f4e71') then raise exception 'other boss changed';end if;end $qa$;select now() observed_at,id,current_hp,max_hp,status from raid_bosses where id='1023c0f0-6025-4d53-af36-ef7cfa4f4e71';commit;
